const actualSeconds = pm.response.responseTime / 1000;
const tolerance = parseFloat(pm.environment.get("tolerancePercent"));

const baselineSeconds = parseFloat(pm.environment.get("baselineSeconds_getDetails"));
const maxAllowedSeconds = baselineSeconds * (1 + tolerance);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test(`GET details response time (${actualSeconds.toFixed(2)}s) is within ${tolerance * 100}% of the baseline (${baselineSeconds}s) — max allowed ${maxAllowedSeconds.toFixed(2)}s`, function () {
    pm.expect(actualSeconds).to.be.below(maxAllowedSeconds);
});

console.log(`[GET details] certifiedProductId=${pm.iterationData.get("certifiedProductId")} actual=${actualSeconds.toFixed(2)}s baseline=${baselineSeconds}s maxAllowed=${maxAllowedSeconds.toFixed(2)}s`);

